#include "stdafx.h"#include "HcdElementBase.h"struct SWVAR_P{#include "PrivateVars/WVAR.h"};class KWVAR : public KHcdElementBase  , protected SWVAR_P{  BYTE* pVarMem;  eHcdVType vType;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void ProjectRestored( SProjRestedParams &params, int N );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _WVAR("WVAR", KWVAR::Create);IHcdElement *KWVAR::Create(){  return new KWVAR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KWVAR, 4 )void KWVAR::InitParm(){#include "PrivateVars/WVAR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KWVAR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KWVAR::ProjectRestored( SProjRestedParams &params, int N ){  if( 1==N )  {    pVarMem = params.pCtrl->GetVarPV( VariableName, &vType );    ASSD( pVarMem );    switch( vType )    {    case ehtAnalog32:    case ehtDigital32:      break;    default:      ASSD(0);      break;    }  }}void KWVAR::StepCalc( SStepCalcParams &params ){  if( !EN )    return;  switch( vType )  {  case ehtAnalog32:    *(tAnalog32*)pVarMem = X;    break;  case ehtDigital32:    *(tDigital32*)pVarMem = (tDigital32)X;    break;  }}